const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));mobile.hidden=!open;menu.querySelector('span').textContent=open?'−':'＋'});
mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.querySelector('span').textContent='＋'}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){mobile.hidden=true;menu.setAttribute('aria-expanded','false')}});
// Sticky header: hide while scrolling down, reveal on scroll up; stays put while the menu is open or focused.
const siteHeader=document.querySelector('header');let lastY=scrollY;
addEventListener('scroll',()=>{const y=Math.max(scrollY,0);if(Math.abs(y-lastY)<6)return;const pin=document.querySelector('.hero-pin');const keep=menu.getAttribute('aria-expanded')==='true'||siteHeader.contains(document.activeElement)||(pin&&pin.getBoundingClientRect().bottom>innerHeight);siteHeader.classList.toggle('is-scrolled',y>8);siteHeader.classList.toggle('is-hidden',!keep&&y>lastY&&y>siteHeader.offsetHeight);mobile.style.top=siteHeader.getBoundingClientRect().bottom+'px';lastY=y},{passive:true});
menu.addEventListener('click',()=>{siteHeader.classList.remove('is-hidden');mobile.style.top=siteHeader.getBoundingClientRect().bottom+'px'});
// Pinned hero: map scroll through the pin to --reveal, holding briefly at each end so both images read fully.
const heroPin=document.querySelector('.hero-pin');
if(heroPin&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const pinnedHero=heroPin.querySelector('.hero');let queued=false;
 const reveal=()=>{queued=false;const travel=heroPin.offsetHeight-pinnedHero.offsetHeight;const p=Math.min(1,Math.max(0,-heroPin.getBoundingClientRect().top/travel));const t=Math.min(1,Math.max(0,(p-.12)/.7));heroPin.style.setProperty('--reveal',(t*t*(3-2*t)).toFixed(3))};
 addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(reveal)}},{passive:true});addEventListener('resize',reveal);reveal()}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-category]').forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter)}));
const studies={focus:{title:'A little space to focus.',description:'A workplace direction that makes concentration feel natural, with a balance of individual workstations, quiet rooms and softer spaces to reset.',points:['Separate focused work from high-traffic areas','Consider daylight, glare and acoustic comfort','Give people a choice of where to work']},together:{title:'A reason to come together.',description:'An inviting shared heart for a team: somewhere to meet, exchange ideas and connect away from the everyday workstation.',points:['Create a welcoming arrival and shared lounge','Plan settings for both quick chats and team sessions','Use materials and colour to express the team’s identity']},flexible:{title:'Built for your next chapter.',description:'A workspace direction for changing teams and changing days. Think adaptable settings and a layout that can respond as your needs evolve.',points:['Discuss future headcount alongside current needs','Use flexible furniture where it supports the brief','Balance collaboration with reliable focus space']}};
const dialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project]').forEach(p=>p.addEventListener('click',()=>{const s=studies[p.dataset.project];document.querySelector('#dialog-title').textContent=s.title;document.querySelector('#dialog-description').textContent=s.description;const ul=document.createElement('ul');s.points.forEach(point=>{const li=document.createElement('li');li.textContent=point;ul.append(li)});document.querySelector('#dialog-points').replaceChildren(ul);dialog.showModal()}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#discuss').addEventListener('click',()=>dialog.close());
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>document.querySelector('#service').value=a.dataset.service));
let lastBrief='';const form=document.querySelector('#inquiry');form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));lastBrief=['SPACE CRAFT — DEMO PROJECT INQUIRY','Demo only. This inquiry has not been sent.','',...Object.entries(data).map(([k,v])=>`${k.charAt(0).toUpperCase()+k.slice(1)}: ${v||'Not supplied'}`)].join('\n');const status=document.querySelector('#form-status');status.replaceChildren();const title=document.createElement('strong');title.textContent='Your demo brief is ready.';const description=document.createElement('p');description.textContent=`Thanks, ${data.name.trim()}. Your ${data.service.toLowerCase()} inquiry has been prepared. Nothing has been sent or saved on a server.`;const download=document.createElement('button');download.type='button';download.textContent='Download your project brief ↓';download.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([lastBrief],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='space-craft-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});status.append(title,description,download);status.hidden=false;status.scrollIntoView({behavior:'smooth',block:'nearest'})});
